gws docs documents get --params '{"documentId":"1ApiRateLimitingPolicySpec000000000000000000"}' --format json 2>/dev/null | python3 -c "
import sys, json
d = json.load(sys.stdin)
content = d['body']['content']
for i, elem in enumerate(content):
    start = elem.get('startIndex', '?')
    end = elem.get('endIndex', '?')
    para = elem.get('paragraph', {})
    if 'elements' in para:
        texts = []
        for e in para['elements']:
            tr = e.get('textRun', {})
            if tr.get('content'):
                texts.append(tr['content'].replace(chr(10), '\\\\n'))
        print(f'[{i}] start={start} end={end} text={\"|\".join(texts)[:200]}')
    else:
        print(f'[{i}] start={start} end={end} (sectionBreak or other)')
